package com.spinplayer.app;
import android.content.Context;import android.system.Os;import java.io.*;import java.util.*;import java.util.zip.*;import java.util.concurrent.atomic.AtomicBoolean;import org.json.*;
/** ARM64 runtime from youtubedl-android; arguments are passed without a shell. */
public final class YtDlpEngine {
 private static final Object INIT_LOCK=new Object();
 public interface Events {void log(String message);boolean cancelled();}
 final Context context;final Events events;final File base,python,ffmpeg,engine,bin;
 public YtDlpEngine(Context c,Events e){context=c;events=e;base=new File(c.getNoBackupFilesDir(),"yt-runtime-1.3");python=new File(base,"python");ffmpeg=new File(base,"ffmpeg");engine=new File(base,"yt-engine.zip");bin=new File(c.getApplicationInfo().nativeLibraryDir);}
 static String asset(Context c,String name)throws IOException{try(InputStream in=c.getAssets().open(name);ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1)out.write(b,0,n);return new String(out.toByteArray(),java.nio.charset.StandardCharsets.UTF_8);}}
 void unpack(String name,File directory,JSONObject links)throws Exception{directory.mkdirs();String prefix=directory.getCanonicalPath()+File.separator;try(ZipInputStream zip=new ZipInputStream(context.getAssets().open(name+"-runtime.zip"))){ZipEntry entry;byte[] b=new byte[65536];while((entry=zip.getNextEntry())!=null){if(events.cancelled())throw new IOException("YtDlpCancelled");File file=new File(directory,entry.getName());if(!file.getCanonicalPath().startsWith(prefix))throw new IOException("RuntimePathInvalid");if(links.has(entry.getName()))continue;if(entry.isDirectory()){file.mkdirs();continue;}file.getParentFile().mkdirs();try(OutputStream out=new FileOutputStream(file)){int n;while((n=zip.read(b))!=-1)out.write(b,0,n);}}}Iterator<String> names=links.keys();while(names.hasNext()){String path=names.next(),target=links.getString(path);File link=new File(directory,path);File resolved=new File(link.getParentFile(),target);if(!resolved.getCanonicalPath().startsWith(prefix))throw new IOException("RuntimeLinkInvalid");link.getParentFile().mkdirs();Os.symlink(target,link.getAbsolutePath());}}
 public void init()throws Exception{synchronized(INIT_LOCK){initLocked();}}
 private void initLocked()throws Exception{if(!new File(bin,"libpython.so").isFile())throw new IOException("Arm64RuntimeMissing");File ready=new File(base,"ready");if(!ready.isFile()){delete(base);base.mkdirs();events.log("YTDLP_RUNTIME_UNPACK_BEGIN");JSONObject links=new JSONObject(asset(context,"runtime-links.json"));unpack("python",python,links.getJSONObject("python"));unpack("ffmpeg",ffmpeg,links.getJSONObject("ffmpeg"));try(InputStream in=context.getAssets().open("yt-engine.zip");OutputStream out=new FileOutputStream(engine)){byte[] b=new byte[65536];int n;while((n=in.read(b))!=-1)out.write(b,0,n);}ready.createNewFile();events.log("YTDLP_RUNTIME_UNPACK_OK");}String version=execute(Collections.singletonList("--version"),false,30000).trim();if(!version.matches("[0-9]{4}\\.[0-9]{2}\\.[0-9]{2}.*"))throw new IOException("YtDlpVersionCheckFailed");events.log("YTDLP_ENGINE_READY version="+version.replaceAll("[^0-9A-Za-z.+_-]",""));}
 static void delete(File file){File[] children=file.listFiles();if(children!=null)for(File f:children)delete(f);file.delete();}
 Map<String,String> environment(){Map<String,String> e=new HashMap<>();e.put("PYTHONHOME",new File(python,"usr").getAbsolutePath());e.put("PYTHONPATH",engine.getAbsolutePath());e.put("LD_LIBRARY_PATH",new File(python,"usr/lib").getAbsolutePath()+":"+new File(ffmpeg,"usr/lib").getAbsolutePath());e.put("SSL_CERT_FILE",new File(python,"usr/etc/tls/cert.pem").getAbsolutePath());e.put("TMPDIR",context.getCacheDir().getAbsolutePath());return e;}
 public String execute(List<String> args,boolean progress,long timeout)throws Exception{ArrayList<String> command=new ArrayList<>();command.add(new File(bin,"libpython.so").getAbsolutePath());command.add("-m");command.add("yt_dlp");command.addAll(args);ProcessBuilder builder=new ProcessBuilder(command);builder.environment().putAll(environment());Process p=builder.start();AtomicBoolean done=new AtomicBoolean(false);StringBuilder errors=new StringBuilder();Thread drain=new Thread(()->{try(BufferedReader reader=new BufferedReader(new InputStreamReader(p.getErrorStream()))){String line;while((line=reader.readLine())!=null){synchronized(errors){if(errors.length()<64000)errors.append(line).append('\n');}}}catch(IOException ignored){}});drain.start();long begin=System.nanoTime();Thread watchdog=new Thread(()->{while(!done.get()){if(events.cancelled()||(System.nanoTime()-begin)/1000000>timeout){p.destroy();return;}try{Thread.sleep(250);}catch(InterruptedException e){return;}}});watchdog.setDaemon(true);watchdog.start();StringBuilder output=new StringBuilder();int code;try{try(BufferedReader reader=new BufferedReader(new InputStreamReader(p.getInputStream()))){String line;while((line=reader.readLine())!=null){if(progress&&line.startsWith("SPIN|")){String safe=line.replaceAll("[^A-Za-z0-9|._ -]","");if(safe.length()<250)events.log("YTDLP_"+safe);}else if(!progress){if(output.length()+line.length()>12*1024*1024)throw new IOException("YtDlpMetadataTooLarge");output.append(line).append('\n');}}}code=p.waitFor();drain.join(2000);}finally{done.set(true);p.destroy();watchdog.interrupt();}if(events.cancelled())throw new IOException("YtDlpCancelled");if(code!=0){String text=errors.toString().toLowerCase(Locale.ROOT);String cause=text.contains("403")?"Http403":text.contains("sign in")||text.contains("login")?"LoginRequired":text.contains("certificate")?"TlsVerification":text.contains("javascript")||text.contains("challenge")?"JsChallenge":text.contains("cannot link")||text.contains("library not found")?"NativeLink":text.contains("permission denied")?"Permission":text.contains("unavailable")?"Unavailable":"Other";events.log("YTDLP_FAILED exit="+code+" category="+cause);throw new IOException("YtDlp"+cause);}events.log("YTDLP_PROCESS_OK elapsed_ms="+(System.nanoTime()-begin)/1000000);return output.toString();}
 public ArrayList<String> defaults(){return new ArrayList<>(Arrays.asList("--ignore-config","--no-cache-dir","--socket-timeout","15","--retries","2","--extractor-retries","1","--js-runtimes","quickjs:"+new File(bin,"libqjs.so").getAbsolutePath(),"--ffmpeg-location",new File(bin,"libffmpeg.so").getAbsolutePath()));}
 public File download(String url,File directory)throws Exception{return download(url,directory,"best");}
 public File download(String url,File directory,String format)throws Exception{String exact=format.startsWith("format:")?format.substring(7):"";if(!exact.isEmpty()&&!exact.matches("[A-Za-z0-9_.-]{1,80}"))throw new IOException("InvalidFormat");directory.mkdirs();ArrayList<String> args=defaults();args.addAll(Arrays.asList("--no-playlist","-f",!exact.isEmpty()?exact:format.equals("aac")?"bestaudio[ext=m4a][acodec^=mp4a][audio_channels<=2]":format.equals("opus")?"bestaudio[acodec^=opus][audio_channels<=2]":"bestaudio[ext=m4a][acodec^=mp4a][audio_channels<=2]/bestaudio[ext=webm][audio_channels<=2]/bestaudio","--abort-on-unavailable-fragments","--concurrent-fragments","4","--throttled-rate","20K","--newline","--progress","--progress-template","download:SPIN|%(progress.status)s|%(progress.downloaded_bytes)s|%(progress.total_bytes_estimate)s|%(progress.speed)s|%(progress.eta)s","-o",new File(directory,"audio.%(ext)s").getAbsolutePath(),url));execute(args,true,600000);File[] files=directory.listFiles((d,name)->name.matches("audio\\.(m4a|mp3|webm|opus|ogg|aac|mp4)"));if(files==null||files.length!=1||files[0].length()==0)throw new IOException("YtDlpOutputMissing");return files[0];}
 public JSONArray searchSoundCloud(String query)throws Exception{
  String term=query.trim();
  if(term.length()<2||term.length()>500)throw new IOException("Введи от 2 до 500 символов");
  ArrayList<String> args=defaults();
  args.addAll(Arrays.asList("--flat-playlist","--skip-download","--dump-single-json","scsearch20:"+term));
  JSONArray entries=new JSONObject(execute(args,false,120000)).getJSONArray("entries");
  JSONArray results=new JSONArray();
  for(int index=0;index<entries.length();index++){
   JSONObject entry=entries.optJSONObject(index);
   if(entry==null)continue;
   String url=entry.optString("webpage_url");
   if(!url.startsWith("https://soundcloud.com/"))continue;
   String cover=entry.optString("thumbnail","");
   JSONArray thumbnails=entry.optJSONArray("thumbnails");
   if(cover.isEmpty()&&thumbnails!=null&&thumbnails.length()>0){
    JSONObject last=thumbnails.optJSONObject(thumbnails.length()-1);
    if(last!=null)cover=last.optString("url");
   }
   results.put(new JSONObject().put("kind","track").put("service","SoundCloud")
    .put("name",entry.optString("title")).put("artist",entry.optString("uploader"))
    .put("duration",entry.optDouble("duration",0)).put("cover",cover).put("url",url));
  }
  return results;
 }
 public JSONObject info(String url)throws Exception{ArrayList<String> args=defaults();args.addAll(Arrays.asList("--no-playlist","--skip-download","--dump-single-json",url));return new JSONObject(execute(args,false,120000));}
 public JSONObject playlist(String url)throws Exception{ArrayList<String> args=defaults();args.addAll(Arrays.asList("--flat-playlist","--skip-download","--dump-single-json","--playlist-end","100",url));return new JSONObject(execute(args,false,120000));}
}
